import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.QQy01QNh.js";const p=JSON.parse('{"title":"A.4　HV04 生成节点（完整接口卡）","description":"","frontmatter":{"title":"A.4　HV04 生成节点（完整接口卡）"},"headers":[],"relativePath":"theory/appendix-a/a-04.md","filePath":"theory/appendix-a/a-04.md"}'),i={name:"theory/appendix-a/a-04.md"};function n(o,t,l,_,b,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<div class="theory-source"><h1 id="section-a-4" tabindex="-1">A.4　HV04 生成节点（完整接口卡） <a class="header-anchor" href="#section-a-4" aria-label="Permalink to &quot;A.4　HV04 生成节点（完整接口卡） {#section-a-4}&quot;">​</a></h1><p>A. 身份、命题与适用范围</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>接口 ID（id）</td><td>HV04</td></tr><tr><td>限定 ID（qualified_id）</td><td>human_variable:HV04</td></tr><tr><td>名称（name）</td><td>生成节点</td></tr><tr><td>主张类型（claim_type）</td><td>H</td></tr><tr><td>合同角色（contract_role）</td><td>human_variable_interface</td></tr><tr><td>命题（proposition）</td><td>生成必须分流为生成条件GC、生成主体GS与生成事件GE，允许无可识别主体的涌现型生成。</td></tr><tr><td>适用范围（scope）</td><td>人类结构中新行动、组织、制度或状态转移的形成</td></tr><tr><td>暂停条件（pause_condition）</td><td>条件被人格化、事件被当作主体或主体资格未经依据确认时，暂停相应主体或分型断言；R0仍可分别登记候选GC、GS、GE及未识别主体状态，不把未识别当作已证明无主体。</td></tr></tbody></table><p>B. 正式依赖与结论边界</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>推理依赖（inferential_requires）</td><td>无（空集合）</td></tr><tr><td>协议依赖（protocol_requires）</td><td>1. EVIDENCE<br>2. SOURCE</td></tr><tr><td>限定／特化（specializes）</td><td>无（空集合）</td></tr><tr><td>适用对象引用（applies_to）</td><td>无（空集合）</td></tr><tr><td>条件支持路由（conditional_support_routes）</td><td>1. route_id=HV04-R0-generation-typing；<br>claim_level=descriptive_classification；<br>when=GC、GS与GE的规定字段可分别登记，并保留无主体涌现与未识别主体状态。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=分别登记候选生成条件、候选生成主体与候选生成事件，不将三者互相替代。；<br>result_ceiling=只到强类型分类；条件、主体或事件任一存在都不证明另两项或因果生成机制。<br>2. route_id=HV04-R1-generation-mechanism；<br>claim_level=mechanism_explanation；<br>when=预注册G2-instance识别GC、GS或无主体涌现通道对指定GE状态转移的超过阈值效应。；<br>additional_inferential_requires=G2-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定尺度、窗口和通道内的候选生成机制及其GC、GS、GE分型。；<br>result_ceiling=不得把条件人格化、把事件倒推为主体，或从生成事实推出正当性、责任与授权。</td></tr><tr><td>允许推论（allowed_inference）</td><td>1. 条件性生成路径2. 有主体或无主体生成</td></tr><tr><td>禁止跳跃（prohibited_leap）</td><td>1. 技术或危机具有意图<br>2. 生成主体自动拥有持续授权</td></tr></tbody></table><p>C. 九轴尺度与对象合同</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>九轴尺度画像（scale_profile）</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;；A=聚合层次：条件暴露、主体行动与生成事件单元，各自个案总体、分布及聚合规则；X=空间范围：生成现场、组织或平台边界、扩散区域与跨域环境；T=时间跨度：条件积累期、主体行动窗、事件时点与扩散时滞；O=组织层级：行动角色、生成团队、组织、制度至治理生态；C=因果层次：生成事件、主体—条件互动机制、中观生成结构、制度安排与系统条件；R=观察分辨率：原始条件行动事件、生成序列、个案、结果分布、转移指标与摘要，并登记压缩损失；I=影响范围：直接生成参与者、承接者、间接受影响者、二阶后果、跨域与代际影响；N=网络拓扑范围：条件传播、主体协作、事件扩散与涌现连接；J=管辖与授权范围：生成识别、启动改变、资源投入及扩散处置分别登记授权；GC、GS、GE分别登记尺度</td></tr><tr><td>有效对象（effective_object）</td><td>形成可检测状态转移的条件、主体与事件组合</td></tr><tr><td>跨尺度保持项（scale_invariants）</td><td>1. GC、GS、GE强类型分离</td></tr><tr><td>升格必补项（required_scale_additions）</td><td>1. 新单位与总体<br>2. 代表关系<br>3. 责任类型<br>4. 外部影响</td></tr><tr><td>随尺度改变项（changing_semantics）</td><td>1. 生成主体、条件与事件可随尺度改变</td></tr><tr><td>不适用对象（non_applicable_objects）</td><td>1. 没有新状态形成或生成主张的稳定描述</td></tr><tr><td>禁止升格（forbidden_elevation）</td><td>1. 把条件或事件升格为有意图主体</td></tr></tbody></table><p>D. 状态、证据与变量流</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>状态集合（state）</td><td>1. 潜在<br>2. 触发<br>3. 形成<br>4. 中断<br>5. 扩散</td></tr><tr><td>可观测项（observables）</td><td>1. 候选条件出现、改变或移除的时间记录<br>2. 生成主体的能力、授权、决策与实际行动<br>3. 生成事件前后预注册状态转移<br>4. 无主体涌现时局部互动与总体结果的桥接记录</td></tr><tr><td>证据要求（evidence）</td><td>1. 启动记录<br>2. 条件窗口<br>3. 主体行动<br>4. 无主体互动机制</td></tr><tr><td>输入依赖与接口内容（input_dependencies）</td><td>1. 指向锚点2. 资源与制度条件3. 因果合同</td></tr><tr><td>输出效应与变量流（output_effects）</td><td>1. 承接需求2. 状态转移3. 责任链起点</td></tr><tr><td>时间窗与时滞（time_window_and_lag）</td><td>登记条件积累、触发事件与形成时滞</td></tr><tr><td>不确定性（uncertainty）</td><td>记录共同生成、无主体涌现和不可识别主体</td></tr><tr><td>局部排除区（local_exclusion_zone）</td><td>被遗漏的非正式启动者与受影响位置</td></tr><tr><td>受影响位置（affected_positions）</td><td>1. 启动者<br>2. 承接者<br>3. 受益者<br>4. 受影响者</td></tr></tbody></table><p>E. 承接、责任、规范、上限与纠错</p><table tabindex="0"><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>承接载体（carrier）</td><td>1. 启动者<br>2. 程序<br>3. 技术设施<br>4. 关系网络</td></tr><tr><td>责任主体（responsible_subject）</td><td>1. 实际行动者2. 决策者3. 授权者</td></tr><tr><td>规范地位（normative_status）</td><td>生成事实不证明正当或责任完整</td></tr><tr><td>判断上限（judgment_ceiling）</td><td>机制链完整时至解释级</td></tr><tr><td>行动上限（action_ceiling）</td><td>本变量只生成GC、GS、GE候选分型、状态转移描述与补证需求，不授权启动、扩散或停止生成过程；任何现实调整须另过C12、运行时显式N前提、J授权与O程序</td></tr><tr><td>反例（counterexamples）</td><td>1. 技术条件被错误描述成具有目标的生成主体<br>2. 无统一发起者的涌现过程被强行归因给一个可见人物</td></tr><tr><td>申诉（appeal）</td><td>依appeal_and_rollback_rule，被归为生成主体者可经安全可达、反报复通道挑战意图、角色与授权归因，并触发与原分型或决策链独立的复核</td></tr><tr><td>回滚（rollback）</td><td>依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内纠正GC、GS、GE类型，实际移除错误意图或责任归因及其下游效力，保留版本与完成验证</td></tr></tbody></table></div>',1)])])}const h=d(i,[["render",n]]);export{p as __pageData,h as default};
